package io.github.diodeme.ji.testkit;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

final class TemporaryWorkspaceTest {
    @Test
    void confinesPathsAndCleansUp() throws Exception {
        Path root;
        try (TemporaryWorkspace workspace = TemporaryWorkspace.create()) {
            root = workspace.root();
            Files.writeString(workspace.resolve("inside.txt"), "safe");
            assertThrows(IllegalArgumentException.class, () -> workspace.resolve("../outside.txt"));
        }
        assertFalse(Files.exists(root));
    }
}
